template:
@php
    // One form sent to the showcase's door (POST webx/widgets/showcase), which answers by §17.4
    // the way a sign-in or a checkout would: the validator's errors on an empty form, then the
    // answer the visitor picks. On the page, or in a dialog a button opens. Every word is the
    // page's: the labels, the answers, the thank-you — the door echoes them back escaped.
    $set = \WebxUi\Widgets\Facades\Widgets::sequence('showcase-sending');
    $dialogId = 'showcase-sending-'.$set;
    $answers = array_filter([
        'message' => (string) $answer_message,
        'redirect' => (string) $answer_redirect,
        'html' => (string) $answer_html,
        'nothing' => (string) $answer_nothing,
    ], static fn (string $label): bool => $label !== '');
    $hidden = [
        'locale' => app()->getLocale(),
        'labels[name]' => (string) $label_name,
        'labels[email]' => (string) $label_email,
        'labels[answer]' => (string) $label_answer,
        'labels[agree]' => (string) $label_agree,
        'words[heading]' => (string) $thanks_heading,
        'words[message]' => (string) $thanks_message,
        'words[step]' => (string) $step,
        'to' => (string) $to,
    ];
@endphp
@php ob_start() @endphp
<x-webx-form :action="route('webx-widgets.showcase')" :id="'showcase-form-'.$set" class="b-showcase-sending__form" novalidate>
    @foreach ($hidden as $hiddenName => $hiddenValue)
        <input type="hidden" name="{{ $hiddenName }}" value="{{ $hiddenValue }}">
    @endforeach
    <x-webx-field name="showcase.name" :label="(string) $label_name" autocomplete="name" required />
    <x-webx-field name="showcase.email" type="email" :label="(string) $label_email" required />
    @if ($answers !== [])
        <x-webx-field name="showcase.answer" type="radio" :label="(string) $label_answer" :choices="$answers" value="message" required />
    @endif
    <x-webx-field name="showcase.agree" type="consent" :label="(string) $label_agree" required />
    <x-webx-form.submit>{{ $button }}</x-webx-form.submit>
</x-webx-form>
@php $form = ob_get_clean() @endphp
<section class="b-showcase-sending" data-wx-block="showcase-sending" data-mode="{{ $mode === 'dialog' ? 'dialog' : 'page' }}">
    @if ($heading)
        <h2 class="b-showcase-sending__heading">{{ $heading }}</h2>
    @endif
    @if ($note)
        <p class="b-showcase-sending__note">{{ $note }}</p>
    @endif
    @if ($mode === 'dialog')
        <a class="b-showcase-sending__open" href="#{{ $dialogId }}" data-webx-dialog="{{ $dialogId }}">{{ $opener }}</a>
        <x-webx-dialog :id="$dialogId" :title="(string) $dialog_title">{!! $form !!}</x-webx-dialog>
    @else
        <div class="b-showcase-sending__frame">{!! $form !!}</div>
    @endif
</section>

styles:
.b-showcase-sending {
    container-type: inline-size;
    max-width: var(--site-container-width);
    margin: 0 auto;
    padding: var(--site-space-6) var(--site-gutter);
}

.b-showcase-sending__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-sending__note {
    max-width: 42rem;
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-sending__frame {
    max-width: 36rem;
}

.b-showcase-sending__open {
    display: inline-flex;
    align-items: center;
    min-height: 44px;
    padding: 0 var(--site-space-5);
    border-radius: var(--site-radius-md);
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
    font-weight: 600;
    text-decoration: none;
}
